{
  "root": "main_stack",
  "state": {
    "workflowSteps": [
      {
        "step_number": "Step 1",
        "description": "Verify the purchase date is within the 30-day window using the receipt or POS system."
      },
      {
        "step_number": "Step 2",
        "description": "Inspect items for condition; they must be unworn, unwashed, and have original tags."
      },
      {
        "step_number": "Step 3",
        "description": "For standard returns, process a full refund to the original payment method."
      },
      {
        "step_number": "Step 4",
        "description": "For defective items, bypass the 30-day rule and offer an immediate exchange or store credit."
      },
      {
        "step_number": "Step 5",
        "description": "Update inventory levels in the system and place returned items in the 'Steam/Restock' bin."
      }
    ],
    "faqItems": [
      {
        "question": "Can we refund to a different card?",
        "answer": "No, refunds must always go to the original payment method for security."
      },
      {
        "question": "What if the tags are missing?",
        "answer": "We only accept returns with original tags unless the item is proven defective."
      },
      {
        "question": "How do we handle gift returns?",
        "answer": "Gift returns are eligible for store credit only, provided the item is in sellable condition."
      },
      {
        "question": "Are sale items returnable?",
        "answer": "Yes, the 30-day window applies to all items unless marked 'Final Sale'."
      },
      {
        "question": "Is there a limit on defective claims?",
        "answer": "No, quality is our priority; defective items are handled case-by-case at any time."
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "header_card",
        "workflow_title",
        "workflow_table",
        "faq_title",
        "faq_table",
        "template_title",
        "email_template_card",
        "actions_title",
        "actions_stack"
      ]
    },
    "header_card": {
      "type": "Card",
      "props": {},
      "children": [
        "header_stack",
        "intro_text"
      ]
    },
    "header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "shop_icon",
        "main_title"
      ]
    },
    "shop_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/shop.svg"
      },
      "children": []
    },
    "main_title": {
      "type": "Text",
      "props": {
        "text": "EcoThreads Return Policy",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Standard Operating Procedure for EcoThreads boutique, Seattle. Effective Date: 2024-05-20."
      },
      "children": []
    },
    "workflow_title": {
      "type": "Text",
      "props": {
        "text": "Return Processing Workflow",
        "variant": "h2"
      },
      "children": []
    },
    "workflow_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "step_number",
            "label": "Step"
          },
          {
            "key": "description",
            "label": "Description"
          }
        ],
        "statePath": "/workflowSteps",
        "domain": "status",
        "preferredPresentation": "cards",
        "primaryColumn": "step_number"
      },
      "children": []
    },
    "faq_title": {
      "type": "Text",
      "props": {
        "text": "Internal Training FAQ",
        "variant": "h2"
      },
      "children": []
    },
    "faq_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "question",
            "label": "Question"
          },
          {
            "key": "answer",
            "label": "Answer"
          }
        ],
        "statePath": "/faqItems",
        "domain": "generic",
        "preferredPresentation": "cards",
        "primaryColumn": "question"
      },
      "children": []
    },
    "template_title": {
      "type": "Text",
      "props": {
        "text": "Customer Notification Template",
        "variant": "h3"
      },
      "children": []
    },
    "email_template_card": {
      "type": "Card",
      "props": {},
      "children": [
        "email_subject_text",
        "email_body_text_1",
        "email_body_text_2",
        "email_signature_text_1",
        "email_signature_text_2"
      ]
    },
    "email_subject_text": {
      "type": "Text",
      "props": {
        "text": "Subject: Your Return at EcoThreads has been Processed",
        "variant": "body"
      },
      "children": []
    },
    "email_body_text_1": {
      "type": "Text",
      "props": {
        "text": "Hello [Customer Name],"
      },
      "children": []
    },
    "email_body_text_2": {
      "type": "Text",
      "props": {
        "text": "We've successfully processed your return for Order #[OrderNumber]. A refund of [Amount] has been initiated to your original payment method. Please allow 5-10 business days for the funds to settle in your account.\n\nThank you for supporting sustainable fashion!"
      },
      "children": []
    },
    "email_signature_text_1": {
      "type": "Text",
      "props": {
        "text": "Best,"
      },
      "children": []
    },
    "email_signature_text_2": {
      "type": "Text",
      "props": {
        "text": "The EcoThreads Team"
      },
      "children": []
    },
    "actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "pos_button",
        "wiki_button"
      ]
    },
    "pos_button": {
      "type": "Button",
      "props": {
        "label": "POS Login"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://pos.ecothreads.com"
          }
        }
      }
    },
    "wiki_button": {
      "type": "Button",
      "props": {
        "label": "Policy Wiki"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://wiki.ecothreads.com/returns"
          }
        }
      }
    }
  }
}
